    "d=\"result\" aria-live=\"polite\"></div>\n  </div>\n</div>\n\n<!-- visitors: problem / solution --",
    ">\n<section class=\"only-guest\">\n  <div class=\"wrap two\">\n    <div>\n      <h2>برای هر کار، ی",
