    "type=\"text\" autocomplete=\"given-name\" maxlength=\"40\" placeholder=\"مثلاً علی\">\n    <div cla",
    "ss=\"msg\" id=\"nameMsg\" role=\"alert\"></div>\n    <button class=\"btn btn-lime btn-lg\" id=\"save",
    "Name\">ادامه</button>\n    <div class=\"links\"><button id=\"skipName\">فعلاً نه</button></div>\n",
    "  </div>\n</dialog>\n\n<script>\n/* ---------------- helpers ---------------- */\nconst $ = s =",
    "> document.querySelector(s);\nconst fa = n => String(n).replace(/\\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[d]",
    ");\nconst en = s => s.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, d =",
    "> '٠١٢٣٤٥٦٧٨٩'.indexOf(d));\nconst nf = n => Number(n).toLocaleString('fa-IR');\nfunction el",
    "(tag, props, ...kids){\n  const e = document.createElement(tag);\n  for(const [k,v] of Objec",
    "t.entries(props || {})){\n    if(k === 'class') e.className = v;\n    else if(k === 'text') ",
    "e.textContent = v;\n    else if(k.startsWith('on')) e.addEventListener(k.slice(2), v);\n    ",
    "else if(v !== false && v != null) e.setAttribute(k, v === true ? '' : v);\n  }\n  for(const ",
    "k of kids.flat()) if(k != null) e.append(k);\n  return e;\n}\nfunction toast(text, kind){\n  c",
    "onst t = $('#toast'); t.textContent = text; t.className = 'toast ' + (kind || ''); t.hidde",
    "n = false;\n  clearTimeout(toast._t); toast._t = setTimeout(() => t.hidden = true, 4500);\n}",
    "\nasync function api(path, opts = {}){\n  try{\n    const r = await fetch(path, {\n      metho",
