    "of j === 'object' && 'success' in j) return {status:r.status, ...j};\n    return {status:r.",
    "status, success:false, error:{code:'BAD_RESPONSE', message:'پاسخ نامعتبر از سرور گرفتیم. د",
    "وباره امتحان کن.'}};\n  }catch(e){\n    return {status:0, success:false, error:{code:'NETWOR",
    "K', message:'اتصال به سرور برقرار نشد. اینترنت رو چک کن و دوباره امتحان کن.'}};\n  }\n}\n\n/* ",
    "---------------- UI copy per tool (labels/costs/availability come from the server) -------",
